\title{Adjacency--Degree Algebras, Cyclic Modules,\\ and the Moment Rigidity of Graphs}
\author{Aristotle}
\date{11 August 2026}

\begin{document}
\maketitle

\begin{abstract}
Let $G$ be a finite simple graph with adjacency matrix $A_G$ and diagonal degree matrix $D_G$.
McKay proved that the collection of spectra of all polynomial functions of $A_G$ and $D_G$
determines a tree up to isomorphism. We study a \emph{principal} --- that is, single-scalar ---
refinement of this invariant: the family of \emph{word moments}
$m_G(w) = \one^{\mathsf T} w(A_G,D_G)\one$, where $w$ ranges over words in the two-letter
alphabet $\{A,D\}$ and $\one$ is the all-ones vector. We situate these moments inside the
\emph{adjacency--degree algebra} $\Alg(G) = \langle I, A_G, D_G\rangle$, its \emph{cyclic module}
$M_G = \Alg(G)\one$, and the \emph{orbit module} $U_G$ of automorphism-invariant vectors.

We prove: (i) $M_G \subseteq U_G$ always, with $M_G = \mathbb R\one$ exactly for regular graphs;
(ii) all word moments are isomorphism invariants and admit a caterpillar normal form, namely
$\one^{\mathsf T} D^{a_0}AD^{a_1}A\cdots AD^{a_n}\one$ equals the sum over walks of length $n$ of
the decoration $\prod_i d_{p_i}^{a_i}$, i.e.\ a degree-decorated caterpillar homomorphism count;
(iii) moment equality forces equality of the order, size, degree distribution, joint degree
distribution along edges, and of \emph{every} degree-decorated walk statistic, while conversely
those walk counts recover all moments, so the two invariants are equally strong;
(iv) moments are computed on the colour-refinement quotient, so the moment-rigidity class lies
inside the one-dimensional Weisfeiler--Leman hierarchy: it is blind on regular graphs of fixed
degree and order and already fails on an explicit connected, non-regular six-vertex pair;
(v) adjoining $J = \one\one^{\mathsf T}$ yields no new scalar data, since
$\one^{\mathsf T} XJY\one = (\one^{\mathsf T} X\one)(\one^{\mathsf T} Y\one)$;
(vi) a degree-transitivity criterion gives $M_G = U_G$, which holds for the infinite family of
stars, and stars are determined by their moments.
These results delimit the determination theorem sharply and reduce the outstanding principal form
of McKay's theorem for trees to a purely combinatorial reconstruction problem.
\end{abstract}

\noindent\textbf{Keywords:} adjacency matrix, degree matrix, cyclic module, graph moments,
caterpillar homomorphism counts, colour refinement, Weisfeiler--Leman, spectral determination of
trees, tight-binding Hamiltonian.

\section{Introduction}

\subsection{Two operators on a network}

Let $G = (V,E)$ be a finite simple graph. Its \emph{adjacency matrix} $A_G \in \mathbb R^{V\times V}$
has entries $(A_G)_{uv} = 1$ if $uv \in E$ and $0$ otherwise, and its \emph{degree matrix} $D_G$ is
diagonal with $(D_G)_{vv} = d_v := \deg_G(v)$.

Physically these are the two canonical ingredients of a tight-binding Hamiltonian on the network:
$A_G$ is the hopping term and $D_G$ the most intrinsic on-site potential the graph supplies. The
Laplacian $L_G = D_G - A_G$ is the simplest combination, but any noncommutative polynomial in
$A_G$ and $D_G$ is a legitimate observable.

\subsection{Cospectrality and McKay's theorem}

The spectrum of $A_G$ alone is a weak invariant: cospectral non-isomorphic graphs abound, and
asymptotically almost every tree has a cospectral mate. McKay's theorem repairs this in the tree
world: the spectra of all polynomial functions of $A_G$ and $D_G$ determine a tree up to
isomorphism. This paper studies the lightest possible shadow of that data --- one real number per
polynomial --- and asks how much survives.

\subsection{The principal invariant}

\begin{definition}[Word moment]
Let $\Sigma = \{A,D\}$ and interpret a word $w = \ell_1\cdots\ell_k \in \Sigma^*$ as the matrix
product $w(A_G,D_G) = M_{\ell_1}\cdots M_{\ell_k}$ with $M_A = A_G$, $M_D = D_G$, the empty word
giving $I$. The \emph{word moment} is
\[
  m_G(w) \;=\; \one^{\mathsf T} w(A_G,D_G)\one \;=\; \sum_{u,v \in V}\bigl(w(A_G,D_G)\bigr)_{uv}.
\]
Graphs $G, G'$ are \emph{moment-equivalent}, written $G \equiv_m G'$, if $m_G(w) = m_{G'}(w)$ for
all $w \in \Sigma^*$.
\end{definition}

Throughout, all graphs are finite, simple and undirected; $n = |V|$; all matrices are real.

\section{The adjacency--degree algebra and its modules}

\begin{definition}
The \emph{adjacency--degree algebra} of $G$ is the unital $\mathbb R$-subalgebra
\[
  \Alg(G) \;=\; \langle I, A_G, D_G\rangle \;=\; \operatorname{span}_{\mathbb R}
    \{\, w(A_G,D_G) : w\in\Sigma^*\,\} \;\subseteq\; \mathbb R^{V\times V}.
\]
\end{definition}

Since $A_G$ and $D_G$ commute only in the regular case, $\Alg(G)$ is genuinely noncommutative in
general.

\begin{definition}[Cyclic module]
$M_G \;=\; \Alg(G)\one \;=\; \{\,X\one : X\in\Alg(G)\,\}\subseteq\mathbb R^V$.
\end{definition}

$M_G$ is exactly the state space the moment data probes: $m_G(w) = \langle \one, w(A,D)\one\rangle$.

\begin{definition}[Orbit module]
$U_G \;=\; \{\, f : V\to\mathbb R \mid f(\sigma v) = f(v)\ \forall \sigma\in\Aut(G),\ v\in V\,\}$.
\end{definition}

\subsection{The ceiling}

\begin{definition}
$X \in \mathbb R^{V\times V}$ is \emph{equivariant} if $X_{\sigma u,\sigma v} = X_{uv}$ for all
$\sigma\in\Aut(G)$ and $u,v$.
\end{definition}

The equivariant matrices form a unital subalgebra: for products, reindex the internal sum along
the bijection $\sigma$,
\[
  (XY)_{\sigma u,\sigma v}=\sum_{t}X_{\sigma u,t}Y_{t,\sigma v}
    =\sum_{s}X_{\sigma u,\sigma s}Y_{\sigma s,\sigma v}=(XY)_{uv},
\]
and scalar matrices are equivariant because $\sigma$ is injective.

\begin{theorem}[Ceiling]\label{thm:ceiling}
For every finite simple graph $G$, $\ M_G \subseteq U_G$.
\end{theorem}

\begin{proof}[Proof sketch]
Both generators are equivariant: for $A_G$ this is the definition of an automorphism, and for
$D_G$ it follows from $\deg(\sigma v) = \deg(v)$ together with injectivity of $\sigma$ for the
off-diagonal entries. Hence $\Alg(G)$ consists of equivariant matrices. If $X$ is equivariant then
$(X\one)(\sigma v)=\sum_u X_{\sigma v,u}=\sum_u X_{\sigma v,\sigma u}=\sum_u X_{vu}=(X\one)(v)$.
\end{proof}

\begin{proposition}[Stability criterion]\label{prop:stab}
Let $N\subseteq\mathbb R^V$ be a linear subspace with $\one\in N$, $A_GN\subseteq N$ and
$D_GN\subseteq N$. Then $M_G\subseteq N$.
\end{proposition}

\begin{proof}[Proof sketch]
The matrices $X$ with $XN\subseteq N$ form a unital subalgebra containing $A_G$ and $D_G$, hence
containing $\Alg(G)$; apply any of its elements to $\one\in N$.
\end{proof}

\subsection{The floor}

\begin{theorem}[Floor]\label{thm:floor}
$M_G = \mathbb R\one$ if and only if $G$ is regular.
\end{theorem}

\begin{proof}[Proof sketch]
($\Rightarrow$) $D_G\one\in\mathbb R\one$ and $(D_G\one)(v)=d_v$, so all degrees coincide.
($\Leftarrow$) If $G$ is $k$-regular, the matrices with constant row sums form a unital subalgebra
(if $X\one=c\one$, $Y\one=c'\one$ then $(XY)\one=c'c\one$) containing $A_G\one=k\one$ and
$D_G\one=k\one$; hence $M_G\subseteq\mathbb R\one$, and $I\in\Alg(G)$ gives the converse inclusion.
\end{proof}

\section{Moments: invariance and first computations}

\begin{theorem}[Isomorphism invariance]\label{thm:inv}
If $f : G \to G'$ is an isomorphism then
$\bigl(w(A_{G'},D_{G'})\bigr)_{f(u)f(v)} = \bigl(w(A_G,D_G)\bigr)_{uv}$
for every word $w$ and all $u,v$, and consequently $m_{G'}(w)=m_G(w)$.
\end{theorem}

\begin{proof}[Proof sketch]
For one letter this is the defining property of an isomorphism ($A$) and degree preservation plus
injectivity ($D$). Induct on $|w|$, reindexing the internal sum along $f$; sum over $u,v$ and
reindex once more.
\end{proof}

\begin{proposition}[Basic moments]\label{prop:basic}
For $G$ on $n$ vertices:
\begin{enumerate}
  \item $m_G(\varepsilon) = n$;
  \item $m_G(D^k) = \sum_v d_v^{\,k}$, the $k$-th degree power sum;
  \item $m_G(A^k) = \sum_{u,v}\#\{\text{walks } u\to v \text{ of length } k\}$;
  \item $m_G(A) = \sum_v d_v = 2|E|$;
  \item $m_G(DAD) = \sum_{u,v}(A_G)_{uv}d_ud_v = 2\sum_{uv\in E}d_ud_v$.
\end{enumerate}
\end{proposition}

\begin{proof}[Proof sketch]
(1),(2) since $D^k$ is diagonal with entries $d_v^k$; (3) is the walk interpretation of powers of
$A$; (4) is (3) with $k=1$ plus the handshake identity; (5) expands $DAD$ entrywise using
diagonality.
\end{proof}

\section{Caterpillar normal form}

Because $D$ is diagonal, every word has the shape
\[
  W(a) \;=\; D^{a_0}A\,D^{a_1}A\cdots A\,D^{a_n},\qquad a=(a_0,\dots,a_n)\in\mathbb N^{n+1},
\]
obtained by letting $n$ be the number of $A$'s and $a_i$ the number of $D$'s between consecutive
$A$'s. We call these \emph{caterpillar words}.

\begin{definition}[Decorated weight]
For $p=(p_0,\dots,p_n)\in V^{n+1}$,
$\ \wt_a(p)=\bigl(\prod_{i<n}(A_G)_{p_ip_{i+1}}\bigr)\prod_{i\le n}d_{p_i}^{\,a_i}$.
The first factor is the indicator that $p$ is a walk, the second the \emph{degree decoration}.
\end{definition}

\begin{theorem}[Caterpillar expansion]\label{thm:cat}
For all $n\ge 0$ and $a\in\mathbb N^{n+1}$,
\[
  m_G\bigl(W(a)\bigr)\;=\;\sum_{p\in V^{n+1}}\wt_a(p)
  \;=\;\sum_{p_0\sim p_1\sim\cdots\sim p_n}\ \prod_{i=0}^{n}d_{p_i}^{\,a_i},
\]
the last sum over all walks of length $n$ in $G$.
\end{theorem}

\begin{proof}[Proof sketch]
Induct on $n$. For $n=0$, $W(a)=D^{a_0}$ is diagonal. For the step, compute coordinatewise
\[
  \bigl(W(a)\one\bigr)(u)=d_u^{\,a_0}\sum_{w}(A_G)_{uw}\bigl(W(a')\one\bigr)(w),
  \qquad a'=(a_1,\dots,a_n),
\]
using diagonality of $D^{a_0}$; the inductive hypothesis identifies the inner vector with the
decorated walk sum from $w$, and peeling the leading vertex gives
$\wt_a(u,w,q)=d_u^{\,a_0}(A_G)_{uw}\wt_{a'}(w,q)$. Summing over $u$ finishes.
\end{proof}

\begin{corollary}[Homomorphism-count form]\label{cor:hom}
Writing $P_n$ for the path with $n+1$ vertices,
\[
  m_G\bigl(W(a)\bigr)=\sum_{\varphi\in\Hom(P_n,G)}\ \prod_{i=0}^{n}d_{\varphi(i)}^{\,a_i}.
\]
Since $d_v^{\,a}$ counts the ordered ways of attaching $a$ legs at $v$, this is the number of
homomorphisms into $G$ of the \emph{caterpillar} formed from the spine $P_n$ by attaching $a_i$
legs at its $i$-th vertex. Word moments are degree-decorated caterpillar homomorphism counts.
\end{corollary}

\begin{corollary}
With $a\equiv 0$ one has $W(0)=A^n$, so plain walk counts are the trivially decorated case.
\end{corollary}

\section{What moment equality determines}

Throughout, $G$ on $V$ and $G'$ on $W$ satisfy $G\equiv_m G'$.

\begin{proposition}
$|V| = |W|$ and $|E(G)| = |E(G')|$.
\end{proposition}

\begin{proof}[Proof sketch]
Take $w=\varepsilon$ and $w=A$ in Proposition~\ref{prop:basic}.
\end{proof}

Write $n=|V|=|W|$; every degree lies in the known node set $\{0,1,\dots,n-1\}$.

\begin{lemma}[Polynomial test functions]\label{lem:test}
If $\sum_{v}d_v^k=\sum_{w}d_w^k$ for all $k$, then $\sum_v q(d_v)=\sum_w q(d_w)$ for every real
polynomial $q$: expand $q=\sum_i q_ix^i$ and exchange summations.
\end{lemma}

\begin{theorem}[Degree distribution]\label{thm:deg}
For every $d\in\mathbb N$, $\ \#\{v\in V:d_v=d\}=\#\{w\in W:d_w=d\}$.
\end{theorem}

\begin{proof}[Proof sketch]
The pure-degree moments give equality of all power sums. Let $\ell_d$ be the Lagrange basis
polynomial on the nodes $\{0,\dots,n-1\}$ with $\ell_d(d)=1$ and $\ell_d(j)=0$ for other nodes.
Then $\sum_v \ell_d(d_v)$ counts vertices of degree $d$; apply Lemma~\ref{lem:test}. For $d\ge n$
both sides vanish.
\end{proof}

\begin{definition}
The \emph{edge statistic} of polynomials $q,r$ is
$S_G(q,r)=\sum_{u,v}(A_G)_{uv}q(d_u)r(d_v)$, and
$N_{a,b}(G)=\#\{(u,v):u\sim v,\ d_u=a,\ d_v=b\}$.
\end{definition}

\begin{lemma}\label{lem:edge}
$S_G(q,r)=\sum_{i,j}q_ir_j\,m_G(D^iAD^j)$ is a finite linear combination of word moments; hence
$G\equiv_m G'$ implies $S_G(q,r)=S_{G'}(q,r)$ for all $q,r$.
\end{lemma}

\begin{theorem}[Joint degree distribution]\label{thm:joint}
$N_{a,b}(G)=N_{a,b}(G')$ for all $a,b$.
\end{theorem}

\begin{proof}[Proof sketch]
For $a,b<n$ take $q=\ell_a$, $r=\ell_b$; then $q(d_u)r(d_v)$ is the indicator of
$\{d_u=a,\ d_v=b\}$ and $S_G(\ell_a,\ell_b)=N_{a,b}(G)$. Apply Lemma~\ref{lem:edge}. Otherwise
both counts vanish.
\end{proof}

\begin{definition}
For weight functions $f_i:\mathbb N\to\mathbb R$ the \emph{decorated walk statistic} is
$T_G(n;f)=\sum_{p_0\sim\cdots\sim p_n}\prod_{i=0}^{n}f_i(d_{p_i})$.
\end{definition}

\begin{lemma}\label{lem:polywalk}
If each $f_i$ is the evaluation of a polynomial $q_i$, then $T_G(n;f)$ is a finite linear
combination $\sum_a\bigl(\prod_i q_{i,a_i}\bigr)m_G(W(a))$ of caterpillar moments.
\end{lemma}

\begin{theorem}[All decorated walk statistics]\label{thm:walkstat}
If $G\equiv_m G'$ then $T_G(n;f)=T_{G'}(n;f)$ for every $n$ and \emph{arbitrary} weight functions
$f_i:\mathbb N\to\mathbb R$.
\end{theorem}

\begin{proof}[Proof sketch]
Only the values $f_i(d)$ with $d<n$ are used, since every degree is $<n$. Replace each $f_i$ by
its interpolating polynomial of degree $<n$ on $\{0,\dots,n-1\}$; this changes neither side, and
Lemma~\ref{lem:polywalk} applies.
\end{proof}

\begin{definition}
For a degree pattern $b\in\mathbb N^{n+1}$,
$c_G(n;b)=\#\{p_0\sim\cdots\sim p_n : d_{p_i}=b_i\ \forall i\}$.
\end{definition}

\begin{corollary}\label{cor:counts}
$G\equiv_m G'$ implies $c_G(n;b)=c_{G'}(n;b)$ for all $n$ and $b$; take
$f_i=\chi_{\{b_i\}}$ in Theorem~\ref{thm:walkstat}. The cases $n=0$ and $n=1$ recover
Theorems~\ref{thm:deg} and~\ref{thm:joint}.
\end{corollary}

\section{Exact equivalence with decorated caterpillar counts}

\begin{lemma}[Regrouping]\label{lem:regroup}
For all $n$ and $a\in\mathbb N^{n+1}$,
\[
  m_G\bigl(W(a)\bigr)=\sum_{b\in\{0,\dots,n-1\}^{n+1}}c_G(n;b)\prod_{i=0}^{n}b_i^{\,a_i}.
\]
\end{lemma}

\begin{proof}[Proof sketch]
Partition the walks of length $n$ by their degree pattern and apply Theorem~\ref{thm:cat}; the
decoration is constant on each class.
\end{proof}

\begin{theorem}[Equivalence]\label{thm:equiv}
Let $G$ and $G'$ have the same number of vertices. Then
\[
  \bigl(\forall n,a\ \ m_G(W(a))=m_{G'}(W(a))\bigr)
  \iff
  \bigl(\forall n,b\ \ c_G(n;b)=c_{G'}(n;b)\bigr),
\]
and since every word is a caterpillar word the left-hand side is exactly $G\equiv_m G'$.
\end{theorem}

\begin{proof}[Proof sketch]
($\Rightarrow$) is Corollary~\ref{cor:counts}. ($\Leftarrow$) is Lemma~\ref{lem:regroup}: both
sides range over the same finite pattern set because the orders agree, and the coefficients
$\prod_i b_i^{a_i}$ do not depend on the graph.
\end{proof}

\begin{remark}
The linear-algebraic invariant and the combinatorial one are literally the same invariant. Any
determination theorem for one is a determination theorem for the other; this converts the
principal McKay question into a pure reconstruction problem.
\end{remark}

\section{Locating the invariant: colour refinement and its failures}

\begin{definition}
A colouring $c:V\to C$ is \emph{equitable} if $c(u)=c(v)$ implies
$\#\{x\in N(u):c(x)=\kappa\}=\#\{x\in N(v):c(x)=\kappa\}$ for every $\kappa\in C$. The stable
colouring produced by colour refinement (one-dimensional Weisfeiler--Leman) is equitable.
\end{definition}

\begin{proposition}\label{prop:eqdeg}
An equitable colouring is degree-preserving: summing the class-wise neighbour counts over all
colours yields the degree.
\end{proposition}

\begin{theorem}[Module bound]\label{thm:colormodule}
Let $c$ be equitable and $C_c=\{f:V\to\mathbb R \mid c(u)=c(v)\Rightarrow f(u)=f(v)\}$. Then
$M_G\subseteq C_c$.
\end{theorem}

\begin{proof}[Proof sketch]
Apply Proposition~\ref{prop:stab}. Clearly $\one\in C_c$. Writing $f=g\circ c$,
\[
  (A_Gf)(u)=\sum_{x\in N(u)}f(x)=\sum_{\kappa}g(\kappa)\,\#\{x\in N(u):c(x)=\kappa\},
\]
which depends only on $c(u)$ by equitability; and $(D_Gf)(u)=d_uf(u)$ depends only on $c(u)$ by
Proposition~\ref{prop:eqdeg}.
\end{proof}

\begin{definition}
Given an equitable $c$ and representatives $\rho:C\to V$ with $c(\rho(c(v)))=c(v)$, set
$B_{\kappa\lambda}=\#\{x\in N(\rho(\kappa)):c(x)=\lambda\}$ and
$\Delta=\operatorname{diag}(d_{\rho(\kappa)})_{\kappa\in C}$; write $|\kappa|$ for the class size.
\end{definition}

\begin{theorem}[Quotient formula]\label{thm:quot}
For every word $w$,
\[
  w(A_G,D_G)\one=\bigl(w(B,\Delta)\one\bigr)\circ c,
  \qquad
  m_G(w)=\sum_{\kappa\in C}|\kappa|\cdot\bigl(w(B,\Delta)\one\bigr)_\kappa.
\]
\end{theorem}

\begin{proof}[Proof sketch]
Induct on $|w|$, the base case being $\one=\one\circ c$. If $w(A,D)\one=h\circ c$ with
$h=w(B,\Delta)\one$, then
$(A_G(h\circ c))(v)=\sum_\lambda h(\lambda)\#\{x\in N(v):c(x)=\lambda\}=(Bh)(c(v))$ by
equitability and the representative property, and the $D$ case uses $d_v=d_{\rho(c(v))}$. Sum over
$v$ and group by class.
\end{proof}

\begin{corollary}[Quotient rigidity]\label{cor:quotrig}
If $G$ and $G'$ carry equitable colourings by the same colour set with equal class sizes, equal
quotient matrices and equal class degrees, then $G\equiv_m G'$ --- whether or not $G\cong G'$.
\end{corollary}

\begin{theorem}[Regular blindness]\label{thm:regular}
If $G$ is $k$-regular on $n$ vertices then $w(A_G,D_G)\one=k^{|w|}\one$ and hence
$m_G(w)=k^{|w|}n$ for every word $w$. Any two $k$-regular graphs of the same order are
moment-equivalent.
\end{theorem}

\begin{proof}[Proof sketch]
Induct on $|w|$: both $A_G\one=k\one$ and $D_G\one=k\one$, so each letter multiplies a scalar
multiple of $\one$ by $k$.
\end{proof}

\begin{corollary}
$C_6$ and $2K_3$ are both $2$-regular on six vertices, hence moment-equivalent, but not
isomorphic: $C_6$ is triangle-free while $2K_3$ contains a triangle.
\end{corollary}

\begin{theorem}[Connected non-regular witness]\label{thm:hex}
Let
\[
  H_1=\bigl(\{0,\dots,5\},\{03,04,05,13,15,23,24\}\bigr),\qquad
  H_2=\bigl(\{0,\dots,5\},\{01,02,05,15,23,24,34\}\bigr).
\]
Then both are connected and non-regular with degree sequence $(3,3,2,2,2,2)$; $H_1\equiv_m H_2$;
and $H_1\not\cong H_2$, since $H_1$ is bipartite with parts $\{0,1,2\},\{3,4,5\}$ (hence
triangle-free) while $H_2$ contains the triangle $\{2,3,4\}$.
\end{theorem}

\begin{proof}[Proof sketch]
In $H_1$, $d_0=d_3=3$ and $d_1=d_2=d_4=d_5=2$; in $H_2$, $d_0=d_2=3$ and $d_1=d_3=d_4=d_5=2$.
Colouring by degree is equitable in both cases, with class sizes $2$ and $4$, class degrees
$\Delta=\operatorname{diag}(3,2)$ and, choosing representatives $0$ and $1$, the same quotient
matrix
\[
  B=\begin{pmatrix}1&2\\1&1\end{pmatrix}.
\]
Corollary~\ref{cor:quotrig} gives moment equivalence; connectivity and the triangle counts are
direct checks.
\end{proof}

\begin{corollary}
The degree-decorated caterpillar counts do not determine connected graphs: by
Theorem~\ref{thm:equiv}, $H_1$ and $H_2$ agree on $c(n;b)$ for every length and pattern.
\end{corollary}

\section{Enlarging the algebra, and where determination succeeds}

Let $J=\one\one^{\mathsf T}$ and consider the ideal $\Alg(G)J\Alg(G)$. On $M_G$ this ideal is very
large --- for connected graphs it acts as the full endomorphism algebra of the module --- but at
the level of scalars:

\begin{theorem}[Ideal factorisation]\label{thm:J}
For all $X,Y\in\mathbb R^{V\times V}$,
$\ \one^{\mathsf T}XJY\one=(\one^{\mathsf T}X\one)(\one^{\mathsf T}Y\one)$.
\end{theorem}

\begin{proof}[Proof sketch]
$(XJY)_{uv}=\sum_{s,t}X_{us}J_{st}Y_{tv}=(\sum_sX_{us})(\sum_tY_{tv})$ since $J_{st}=1$; summing
over $u,v$ factorises.
\end{proof}

\begin{corollary}
Every moment of an element of $\Alg(G)J\Alg(G)$ is a product of word moments: the principal moment
data is exactly the word data.
\end{corollary}

\begin{lemma}[Degree indicators]\label{lem:degind}
With $\ell_d$ as in Theorem~\ref{thm:deg}, $\ \ell_d(D_G)\one=\chi_{\{v:d_v=d\}}\in M_G$,
because $D^i\one$ is the vector $v\mapsto d_v^{\,i}$ and $M_G$ is a linear space. Hence every
function of the degree lies in $M_G$.
\end{lemma}

\begin{theorem}[Degree-transitivity criterion]\label{thm:degtrans}
If $d_u=d_v$ implies the existence of $\sigma\in\Aut(G)$ with $\sigma(u)=v$, then $M_G=U_G$.
\end{theorem}

\begin{proof}[Proof sketch]
``$\subseteq$'' is Theorem~\ref{thm:ceiling}. For ``$\supseteq$'', if $f\in U_G$ and $d_u=d_v$,
pick $\sigma$ with $\sigma(u)=v$; then $f(v)=f(\sigma u)=f(u)$, so $f$ is a function of the degree
and Lemma~\ref{lem:degind} applies.
\end{proof}

\begin{theorem}[Stars]\label{thm:star}
For every $n$, $M_{K_{1,n}}=U_{K_{1,n}}$; and if $K_{1,n}\equiv_m K_{1,m}$ then $n=m$, so stars are
determined by their moments.
\end{theorem}

\begin{proof}[Proof sketch]
Any two leaves are exchanged by the transposition swapping them, which is an automorphism because
adjacency in a star only records ``is the centre''; a leaf and the centre share a degree only when
$n=1$, where the vertex swap of $K_2$ is an automorphism. Apply Theorem~\ref{thm:degtrans}. For
determination, the empty word gives $n+1=m+1$.
\end{proof}

\begin{theorem}[The rigidity boundary]\label{thm:boundary}
All of the following hold simultaneously:
\begin{enumerate}
  \item for all $n,m$, if $K_{1,n}\equiv_m K_{1,m}$ then $K_{1,n}\cong K_{1,m}$;
  \item $C_6\equiv_m 2K_3$ but $C_6\not\cong 2K_3$;
  \item $H_1\equiv_m H_2$ with both connected and non-regular, but $H_1\not\cong H_2$.
\end{enumerate}
\end{theorem}

\section{Algorithms and complexity}

Let $G$ have $n$ vertices and $m$ edges, given by adjacency lists.

\paragraph{Computing a moment.} Never form $w(A,D)$. Propagate $x\leftarrow\one$ through the
letters of $w$ from right to left: for $A$, $x'(u)=\sum_{v\in N(u)}x(v)$ at cost $O(m)$; for $D$,
$x'(u)=d_ux(u)$ at cost $O(n)$. Then $m_G(w)=\sum_u x(u)$. Total cost $O(|w|(n+m))$ with $O(n)$
memory. All moments of all words of length $\le L$ cost $O(2^L(n+m))$ with suffix sharing.

\paragraph{Computing decorated walk counts.} By Theorem~\ref{thm:equiv} one may equally compute
$c_G(n;b)$ by dynamic programming: with $S_0[v]=[\,d_v=b_0\,]$ and
$S_{k+1}[u]=[\,d_u=b_{k+1}\,]\sum_{v\in N(u)}S_k[v]$, one has $c_G(n;b)=\sum_uS_n[u]$; each
layer costs one $O(m)$ pass.

\paragraph{Pre-testing with colour refinement.} Colour refinement runs in $O((n+m)\log n)$. By
Corollary~\ref{cor:quotrig}, if the stable class sizes and quotient matrices agree, the graphs are
moment-equivalent and no further computation is needed: moments are worth computing only when
colour refinement already separates the graphs, in which case they provide a compact numerical
certificate.

\paragraph{Interpolation.} Recovering the degree or joint-degree distributions from raw moments
means inverting Vandermonde systems on the nodes $0,\dots,n-1$; these are ill-conditioned in
floating point, so exact arithmetic (or direct combinatorial counting) is recommended beyond
$n\approx 20$.

\section{Applications and interpretation}

\paragraph{Tight-binding physics.} The family $\{A+tD\}$ is the one-parameter family of
tight-binding Hamiltonians with degree-proportional on-site energies ($t=-1$ giving minus the
Laplacian). The word moments are the uniform-state expectation values of all noncommutative
observables built from hopping and potential, and Theorem~\ref{thm:regular} says that on a regular
lattice the entire family degenerates: all such expectations are fixed by degree, order and word
length. Structure becomes visible only when the coordination number varies.

\paragraph{Network fingerprinting.} The moments are strictly stronger than the degree sequence
(they see the joint degree distribution) and strictly stronger than plain walk counts (the
trivially decorated case), are permutation-invariant by construction, and cost a handful of sparse
matrix--vector products.

\paragraph{Graph learning.} Message-passing architectures that aggregate neighbour features compute,
in their early rounds, exactly degree-decorated walk statistics. Theorem~\ref{thm:equiv} identifies
the moment invariant with those statistics and Theorem~\ref{thm:colormodule} caps its power at
colour refinement; the pair $H_1,H_2$ is a minimal connected non-regular certificate of that cap.

\section{Open problems and future directions}

\begin{conjecture}[Principal McKay theorem]
If $T_1,T_2$ are trees with $m_{T_1}(w)=m_{T_2}(w)$ for every word $w$, then $T_1\cong T_2$.
\end{conjecture}

\noindent\emph{Status.} Proved above for stars; exhaustive enumeration finds no counterexample
among trees on at most twelve vertices, where undecorated walk counts already collide.
By Theorem~\ref{thm:equiv} the invariant is exactly the family of
degree-decorated caterpillar counts, so the statement is a purely combinatorial reconstruction
problem: rebuild a tree from the number of walks realising each prescribed degree pattern, peeling
leaves by their decorated pattern multiplicities.

\begin{conjecture}[Forest module identity]
For every forest $F$, $M_F=U_F$.
\end{conjecture}

\noindent\emph{Status.} Proved above for stars and for degree-transitive graphs. The expected
mechanism is that in a forest the iterated degree refinement already stabilises at the
automorphism-orbit partition, so the inclusion $M_G\subseteq U_G$ becomes an equality.

\medskip

\noindent Further directions: classify the minimal moment-equivalent non-isomorphic pairs beyond
the regular ones (in particular the ten-vertex integral switchings invisible to the cyclic module);
bound quantitatively how many moments separate two trees on $n$ vertices; develop higher-order
analogues indexed by the $k$-dimensional Weisfeiler--Leman hierarchy; extend to weighted and
directed graphs, where $D$ splits into in- and out-degree matrices; and determine exactly which
graphs the full spectra separate but the principal moments do not.

\section*{Summary of main results}

\begin{center}
\begin{tabular}{ll}
\toprule
Result & Statement \\
\midrule
Ceiling & $M_G\subseteq U_G$ for every finite simple graph \\
Floor & $M_G=\mathbb R\one$ iff $G$ is regular \\
Invariance & All word moments are isomorphism invariants \\
Caterpillar expansion & $\one^{\mathsf T}D^{a_0}A\cdots AD^{a_n}\one=\sum_{\text{walks}}\prod_i d_{p_i}^{a_i}$ \\
Degree recovery & Moment equality $\Rightarrow$ equal order, size, degree distribution \\
Joint degrees & Moment equality $\Rightarrow$ equal counts $N_{a,b}$ \\
Walk statistics & Moment equality $\Rightarrow$ every decorated walk statistic agrees \\
Equivalence & Moments $\iff$ decorated walk counts (same order) \\
Quotient formula & $m_G(w)=\sum_\kappa|\kappa|(w(B,\Delta)\one)_\kappa$ \\
Regular blindness & $k$-regular on $n$ vertices $\Rightarrow m_G(w)=k^{|w|}n$ \\
Six-vertex failure & Connected non-regular moment-equivalent non-isomorphic pair \\
$J$-ideal & $\one^{\mathsf T}XJY\one=(\one^{\mathsf T}X\one)(\one^{\mathsf T}Y\one)$ \\
Degree transitivity & Degree-transitive $\Rightarrow M_G=U_G$ \\
Stars & $M_{K_{1,n}}=U_{K_{1,n}}$, and moments determine stars \\
\bottomrule
\end{tabular}
\end{center}

\end{document}

demo:
"""
Adjacency-degree algebras and moment rigidity of graphs
=======================================================

Self-contained numerical demonstration of the results:

  * word moments  m_G(w) = 1^T w(A, D) 1  are isomorphism invariants;
  * the caterpillar expansion
        1^T D^{a_0} A D^{a_1} A ... A D^{a_n} 1
          = sum over walks p_0 ~ ... ~ p_n of  prod_i deg(p_i)^{a_i};
  * moment equality implies equality of the degree distribution and of the
    joint degree distribution N_{a,b};
  * moments equal decorated caterpillar walk counts in strength;
  * the cyclic module M_G = <I, A, D> 1 sits inside the orbit module U_G,
    and dim M_G = 1 exactly for regular graphs;
  * regular blindness:  m_G(w) = k^{|w|} n  for every k-regular graph;
  * the quotient formula on an equitable colouring, and the connected
    non-regular six-vertex pair H1, H2 that it certifies as
    moment-equivalent but non-isomorphic.

Pure Python + standard library only (fractions used for exact arithmetic).
Run:  python demo.py
"""

from __future__ import annotations

from fractions import Fraction
from itertools import combinations, permutations, product
from typing import Dict, Iterable, List, Sequence, Tuple

Graph = List[List[int]]  # adjacency matrix as a list of rows of 0/1
Word = str  # a string over the alphabet {"A", "D"}


# ----------------------------------------------------------------------
# Graph construction helpers
# ----------------------------------------------------------------------


def graph_from_edges(n: int, edges: Iterable[Tuple[int, int]]) -> Graph:
    """Build the n-vertex adjacency matrix of a simple graph from an edge list."""
    adj: Graph = [[0] * n for _ in range(n)]
    for u, v in edges:
        if u == v:
            raise ValueError("simple graphs have no loops")
        adj[u][v] = 1
        adj[v][u] = 1
    return adj


def degrees(adj: Graph) -> List[int]:
    """Degree sequence, indexed by vertex."""
    return [sum(row) for row in adj]


def edge_list(adj: Graph) -> List[Tuple[int, int]]:
    """Undirected edges as sorted pairs."""
    n = len(adj)
    return [(u, v) for u in range(n) for v in range(u + 1, n) if adj[u][v]]


def is_connected(adj: Graph) -> bool:
    """Breadth-first reachability from vertex 0."""
    n = len(adj)
    if n == 0:
        return True
    seen = {0}
    stack = [0]
    while stack:
        u = stack.pop()
        for v in range(n):
            if adj[u][v] and v not in seen:
                seen.add(v)
                stack.append(v)
    return len(seen) == n


def triangle_count(adj: Graph) -> int:
    """Number of unordered triangles."""
    n = len(adj)
    return sum(
        1
        for a, b, c in combinations(range(n), 3)
        if adj[a][b] and adj[b][c] and adj[a][c]
    )


def is_isomorphic(g1: Graph, g2: Graph) -> bool:
    """Brute-force isomorphism test (only used on tiny graphs)."""
    n = len(g1)
    if n != len(g2) or sorted(degrees(g1)) != sorted(degrees(g2)):
        return False
    for perm in permutations(range(n)):
        if all(g1[u][v] == g2[perm[u]][perm[v]] for u in range(n) for v in range(n)):
            return True
    return False


# ----------------------------------------------------------------------
# Word moments
# ----------------------------------------------------------------------


def apply_letter(adj: Graph, deg: Sequence[int], letter: str,
                 x: Sequence[Fraction]) -> List[Fraction]:
    """Apply A (hopping) or D (degree potential) to a vector, in O(n^2)/O(n)."""
    n = len(adj)
    if letter == "A":
        return [sum(x[v] for v in range(n) if adj[u][v]) for u in range(n)]
    if letter == "D":
        return [Fraction(deg[u]) * x[u] for u in range(n)]
    raise ValueError(f"unknown letter {letter!r}")


def word_moment(adj: Graph, word: Word) -> Fraction:
    """m_G(w) = 1^T w(A, D) 1, computed by right-to-left vector propagation."""
    n = len(adj)
    deg = degrees(adj)
    x: List[Fraction] = [Fraction(1)] * n
    for letter in reversed(word):
        x = apply_letter(adj, deg, letter, x)
    return sum(x, Fraction(0))


def all_words(max_len: int) -> List[Word]:
    """All words over {A, D} of length at most max_len, shortest first."""
    words: List[Word] = [""]
    for length in range(1, max_len + 1):
        words.extend("".join(t) for t in product("AD", repeat=length))
    return words


def moment_vector(adj: Graph, max_len: int) -> Dict[Word, Fraction]:
    """The full moment table up to a given word length."""
    return {w: word_moment(adj, w) for w in all_words(max_len)}


def moment_equivalent(g1: Graph, g2: Graph, max_len: int = 6) -> bool:
    """Test moment equality for all words up to a given length."""
    return moment_vector(g1, max_len) == moment_vector(g2, max_len)


# ----------------------------------------------------------------------
# Caterpillar expansion: moments as decorated walk sums
# ----------------------------------------------------------------------


def caterpillar_word(exponents: Sequence[int]) -> Word:
    """D^{a_0} A D^{a_1} A ... A D^{a_n} as a word over {A, D}."""
    return "A".join("D" * a for a in exponents)


def decorated_walk_sum(adj: Graph, exponents: Sequence[int]) -> Fraction:
    """Sum over all walks p_0 ~ ... ~ p_n of prod_i deg(p_i)^{a_i}, by brute force."""
    n_hops = len(exponents) - 1
    n = len(adj)
    deg = degrees(adj)
    total = Fraction(0)
    for walk in product(range(n), repeat=n_hops + 1):
        if all(adj[walk[i]][walk[i + 1]] for i in range(n_hops)):
            weight = Fraction(1)
            for i, a in enumerate(exponents):
                weight *= Fraction(deg[walk[i]]) ** a
            total += weight
    return total


def decorated_walk_count(adj: Graph, pattern: Sequence[int]) -> int:
    """c_G(n; b): number of walks whose degree sequence is exactly `pattern`."""
    n_hops = len(pattern) - 1
    n = len(adj)
    deg = degrees(adj)
    count = 0
    for walk in product(range(n), repeat=n_hops + 1):
        if all(adj[walk[i]][walk[i + 1]] for i in range(n_hops)) and all(
            deg[walk[i]] == pattern[i] for i in range(n_hops + 1)
        ):
            count += 1
    return count


def all_decorated_walk_counts(adj: Graph, n_hops: int) -> Dict[Tuple[int, ...], int]:
    """All nonzero decorated walk counts of a given length."""
    n = len(adj)
    deg = degrees(adj)
    counts: Dict[Tuple[int, ...], int] = {}
    for walk in product(range(n), repeat=n_hops + 1):
        if all(adj[walk[i]][walk[i + 1]] for i in range(n_hops)):
            key = tuple(deg[v] for v in walk)
            counts[key] = counts.get(key, 0) + 1
    return counts


# ----------------------------------------------------------------------
# Degree and joint-degree statistics
# ----------------------------------------------------------------------


def degree_distribution(adj: Graph) -> Dict[int, int]:
    """Number of vertices of each degree."""
    dist: Dict[int, int] = {}
    for d in degrees(adj):
        dist[d] = dist.get(d, 0) + 1
    return dist


def joint_degree_counts(adj: Graph) -> Dict[Tuple[int, int], int]:
    """N_{a,b}: ordered adjacent pairs (u, v) with deg u = a, deg v = b."""
    n = len(adj)
    deg = degrees(adj)
    counts: Dict[Tuple[int, int], int] = {}
    for u in range(n):
        for v in range(n):
            if adj[u][v]:
                key = (deg[u], deg[v])
                counts[key] = counts.get(key, 0) + 1
    return counts


def lagrange_basis(nodes: Sequence[int], target: int) -> List[Fraction]:
    """Coefficients of the Lagrange basis polynomial that is 1 at `target`, 0 elsewhere."""
    coeffs = [Fraction(1)]
    for node in nodes:
        if node == target:
            continue
        # multiply by (x - node) / (target - node)
        scale = Fraction(1, target - node)
        new = [Fraction(0)] * (len(coeffs) + 1)
        for i, c in enumerate(coeffs):
            new[i + 1] += c * scale
            new[i] -= c * node * scale
        coeffs = new
    return coeffs


def degree_distribution_from_moments(moments: Dict[Word, Fraction], n: int) -> Dict[int, int]:
    """Recover the degree distribution from the pure-degree moments 1^T D^k 1."""
    power_sums = [moments["D" * k] for k in range(n)]
    nodes = list(range(n))
    dist: Dict[int, int] = {}
    for d in nodes:
        coeffs = lagrange_basis(nodes, d)
        value = sum(c * power_sums[i] for i, c in enumerate(coeffs))
        if value != 0:
            dist[d] = int(value)
    return dist


def joint_degree_from_moments(adj: Graph, n: int) -> Dict[Tuple[int, int], int]:
    """Recover N_{a,b} from the moments 1^T D^i A D^j 1 by double interpolation."""
    raw = {
        (i, j): word_moment(adj, "D" * i + "A" + "D" * j)
        for i in range(n)
        for j in range(n)
    }
    nodes = list(range(n))
    out: Dict[Tuple[int, int], int] = {}
    for a in nodes:
        ca = lagrange_basis(nodes, a)
        for b in nodes:
            cb = lagrange_basis(nodes, b)
            value = sum(
                ca[i] * cb[j] * raw[(i, j)]
                for i in range(len(ca))
                for j in range(len(cb))
            )
            if value != 0:
                out[(a, b)] = int(value)
    return out


# ----------------------------------------------------------------------
# The cyclic module M_G and the orbit module U_G
# ----------------------------------------------------------------------


def rref_rank(rows: List[List[Fraction]]) -> int:
    """Rank of a matrix over the rationals by Gaussian elimination."""
    mat = [row[:] for row in rows]
    rank = 0
    ncols = len(mat[0]) if mat else 0
    for col in range(ncols):
        pivot = next((r for r in range(rank, len(mat)) if mat[r][col] != 0), None)
        if pivot is None:
            continue
        mat[rank], mat[pivot] = mat[pivot], mat[rank]
        inv = Fraction(1) / mat[rank][col]
        mat[rank] = [x * inv for x in mat[rank]]
        for r in range(len(mat)):
            if r != rank and mat[r][col] != 0:
                factor = mat[r][col]
                mat[r] = [x - factor * y for x, y in zip(mat[r], mat[rank])]
        rank += 1
    return rank


def cyclic_module_basis(adj: Graph, max_len: int = 8) -> List[List[Fraction]]:
    """Vectors w(A, D) 1 for all words w up to a given length (a spanning set of M_G)."""
    n = len(adj)
    deg = degrees(adj)
    vectors: List[List[Fraction]] = []
    for word in all_words(max_len):
        x: List[Fraction] = [Fraction(1)] * n
        for letter in reversed(word):
            x = apply_letter(adj, deg, letter, x)
        vectors.append(x)
    return vectors


def cyclic_module_dimension(adj: Graph, max_len: int = 8) -> int:
    """dim M_G, computed from a spanning set (stabilises well before max_len)."""
    return rref_rank(cyclic_module_basis(adj, max_len))


def automorphisms(adj: Graph) -> List[Tuple[int, ...]]:
    """All automorphisms, by brute force (tiny graphs only)."""
    n = len(adj)
    return [
        perm
        for perm in permutations(range(n))
        if all(adj[u][v] == adj[perm[u]][perm[v]] for u in range(n) for v in range(n))
    ]


def orbit_partition(adj: Graph) -> List[List[int]]:
    """Orbits of the automorphism group on vertices."""
    n = len(adj)
    auts = automorphisms(adj)
    seen = [False] * n
    orbits: List[List[int]] = []
    for v in range(n):
        if seen[v]:
            continue
        orbit = sorted({perm[v] for perm in auts})
        for u in orbit:
            seen[u] = True
        orbits.append(orbit)
    return orbits


def orbit_module_dimension(adj: Graph) -> int:
    """dim U_G = number of automorphism orbits."""
    return len(orbit_partition(adj))


# ----------------------------------------------------------------------
# Colour refinement and the quotient formula
# ----------------------------------------------------------------------


def colour_refinement(adj: Graph) -> List[int]:
    """Stable colouring (1-WL): returns a canonical integer colour per vertex."""
    n = len(adj)
    colours = [0] * n
    while True:
        signature = [
            (colours[u], tuple(sorted(colours[v] for v in range(n) if adj[u][v])))
            for u in range(n)
        ]
        order = {sig: i for i, sig in enumerate(sorted(set(signature)))}
        new = [order[sig] for sig in signature]
        if new == colours:
            return colours
        colours = new


def is_equitable(adj: Graph, colouring: Sequence[int]) -> bool:
    """Check the equitable-partition condition directly."""
    n = len(adj)
    palette = sorted(set(colouring))
    for u in range(n):
        for v in range(n):
            if colouring[u] != colouring[v]:
                continue
            for kappa in palette:
                cu = sum(1 for w in range(n) if adj[u][w] and colouring[w] == kappa)
                cv = sum(1 for w in range(n) if adj[v][w] and colouring[w] == kappa)
                if cu != cv:
                    return False
    return True


def quotient_data(adj: Graph, colouring: Sequence[int]):
    """Class sizes, quotient matrix B, and class degrees Delta of an equitable colouring."""
    n = len(adj)
    palette = sorted(set(colouring))
    sizes = [sum(1 for v in range(n) if colouring[v] == kappa) for kappa in palette]
    reps = [next(v for v in range(n) if colouring[v] == kappa) for kappa in palette]
    deg = degrees(adj)
    quot = [
        [sum(1 for w in range(n) if adj[r][w] and colouring[w] == lam) for lam in palette]
        for r in reps
    ]
    class_deg = [deg[r] for r in reps]
    return sizes, quot, class_deg


def quotient_moment(sizes: Sequence[int], quot: Sequence[Sequence[int]],
                    class_deg: Sequence[int], word: Word) -> Fraction:
    """sum_kappa |kappa| * (w(B, Delta) 1)_kappa -- the quotient formula's right-hand side."""
    c = len(sizes)
    x: List[Fraction] = [Fraction(1)] * c
    for letter in reversed(word):
        if letter == "A":
            x = [sum(Fraction(quot[k][l]) * x[l] for l in range(c)) for k in range(c)]
        else:
            x = [Fraction(class_deg[k]) * x[k] for k in range(c)]
    return sum(Fraction(sizes[k]) * x[k] for k in range(c))


# ----------------------------------------------------------------------
# Named graphs
# ----------------------------------------------------------------------


def star(n_leaves: int) -> Graph:
    """K_{1,n}: centre 0 joined to n leaves."""
    return graph_from_edges(n_leaves + 1, [(0, i) for i in range(1, n_leaves + 1)])


def path(n: int) -> Graph:
    """The path on n vertices."""
    return graph_from_edges(n, [(i, i + 1) for i in range(n - 1)])


def cycle(n: int) -> Graph:
    """The cycle C_n."""
    return graph_from_edges(n, [(i, (i + 1) % n) for i in range(n)])


def two_triangles() -> Graph:
    """2K_3: two disjoint triangles on six vertices."""
    return graph_from_edges(6, [(0, 1), (1, 2), (0, 2), (3, 4), (4, 5), (3, 5)])


HEX1_EDGES = [(0, 3), (0, 4), (0, 5), (1, 3), (1, 5), (2, 3), (2, 4)]
HEX2_EDGES = [(0, 1), (0, 2), (0, 5), (1, 5), (2, 3), (2, 4), (3, 4)]


def hex1() -> Graph:
    """H1: the triangle-free (bipartite) six-vertex witness."""
    return graph_from_edges(6, HEX1_EDGES)


def hex2() -> Graph:
    """H2: the six-vertex witness containing a triangle."""
    return graph_from_edges(6, HEX2_EDGES)


def relabel(adj: Graph, perm: Sequence[int]) -> Graph:
    """Relabel vertices: new vertex perm[u] plays the role of old vertex u."""
    n = len(adj)
    out: Graph = [[0] * n for _ in range(n)]
    for u in range(n):
        for v in range(n):
            out[perm[u]][perm[v]] = adj[u][v]
    return out


# ----------------------------------------------------------------------
# Demonstrations
# ----------------------------------------------------------------------


def banner(title: str) -> None:
    print()
    print("=" * 72)
    print(title)
    print("=" * 72)


def demo_basic_moments() -> None:
    banner("1. Basic moments: order, size, degree power sums, decorated edges")
    g = path(5)
    n = len(g)
    print(f"Graph: path on {n} vertices, degrees {degrees(g)}")
    print(f"  m(empty)  = {word_moment(g, '')}        (= number of vertices {n})")
    print(f"  m(A)      = {word_moment(g, 'A')}        (= 2|E| = {2 * len(edge_list(g))})")
    for k in range(1, 4):
        lhs = word_moment(g, "D" * k)
        rhs = sum(d ** k for d in degrees(g))
        print(f"  m(D^{k})    = {lhs}       (= sum of d^{k} = {rhs})  match: {lhs == rhs}")
    deg = degrees(g)
    rhs = sum(2 * deg[u] * deg[v] for u, v in edge_list(g))
    print(f"  m(DAD)    = {word_moment(g, 'DAD')}      (= 2 * sum_{{uv in E}} d_u d_v = {rhs})")


def demo_isomorphism_invariance() -> None:
    banner("2. Word moments are isomorphism invariants")
    g = hex1()
    perm = (3, 1, 5, 0, 2, 4)
    h = relabel(g, perm)
    same = moment_equivalent(g, h, max_len=5)
    print(f"Relabelling H1 by the permutation {perm}.")
    print(f"  All moments of words of length <= 5 agree: {same}")
    print(f"  Sample: m(ADDA) = {word_moment(g, 'ADDA')} vs {word_moment(h, 'ADDA')}")


def demo_caterpillar_expansion() -> None:
    banner("3. Caterpillar expansion: moments are decorated walk sums")
    g = hex1()
    print("Checking  m(D^{a0} A D^{a1} A ... ) = sum over walks of prod deg(p_i)^{a_i}")
    for exps in [(0, 0), (1, 0), (1, 1), (2, 1), (0, 1, 0), (1, 0, 2), (2, 2, 1)]:
        word = caterpillar_word(exps)
        lhs = word_moment(g, word)
        rhs = decorated_walk_sum(g, exps)
        label = word if word else "(empty)"
        print(f"  a = {str(exps):12s} word = {label:12s} moment = {str(lhs):>8s} "
              f"walk sum = {str(rhs):>8s}  match: {lhs == rhs}")


def demo_degree_recovery() -> None:
    banner("4. Recovering the degree and joint degree distributions from moments")
    g = hex2()
    n = len(g)
    moments = moment_vector(g, max_len=n)
    recovered = degree_distribution_from_moments(moments, n)
    actual = degree_distribution(g)
    print(f"Graph H2, degrees {degrees(g)}")
    print(f"  degree distribution, direct      : {dict(sorted(actual.items()))}")
    print(f"  recovered by interpolation from moments 1^T D^k 1: "
          f"{dict(sorted(recovered.items()))}")
    print(f"  match: {actual == recovered}")
    joint_direct = joint_degree_counts(g)
    joint_moment = joint_degree_from_moments(g, n)
    print(f"  joint degrees N_(a,b), direct    : {dict(sorted(joint_direct.items()))}")
    print(f"  recovered from moments D^i A D^j : {dict(sorted(joint_moment.items()))}")
    print(f"  match: {joint_direct == joint_moment}")


def demo_modules() -> None:
    banner("5. The cyclic module M_G, the orbit module U_G, and regularity")
    examples = [
        ("path P_5", path(5)),
        ("star K_{1,4}", star(4)),
        ("cycle C_6 (2-regular)", cycle(6)),
        ("2K_3 (2-regular)", two_triangles()),
        ("H1", hex1()),
        ("H2", hex2()),
    ]
    print(f"{'graph':<24}{'dim M_G':>9}{'dim U_G':>9}{'regular':>10}")
    for name, g in examples:
        dm = cyclic_module_dimension(g)
        du = orbit_module_dimension(g)
        reg = len(set(degrees(g))) == 1
        print(f"{name:<24}{dm:>9}{du:>9}{str(reg):>10}")
    print()
    print("  Ceiling  M_G <= U_G  is visible as dim M_G <= dim U_G in every row.")
    print("  Floor    dim M_G = 1 occurs exactly in the regular rows.")
    print("  Stars attain the ceiling: dim M = dim U.")


def demo_regular_blindness() -> None:
    banner("6. Regular blindness: k-regular graphs of the same order are moment-equal")
    g1, g2 = cycle(6), two_triangles()
    print("C_6 versus 2K_3, both 2-regular on 6 vertices.")
    print(f"{'word':<10}{'m(C_6)':>10}{'m(2K_3)':>10}{'2^|w| * 6':>12}")
    for word in ["", "A", "D", "AD", "DA", "ADD", "DADA"]:
        predicted = 2 ** len(word) * 6
        print(f"{(word or '(empty)'):<10}{str(word_moment(g1, word)):>10}"
              f"{str(word_moment(g2, word)):>10}{predicted:>12}")
    print(f"  moment-equivalent (length <= 6): {moment_equivalent(g1, g2, 6)}")
    print(f"  isomorphic                     : {is_isomorphic(g1, g2)}")
    print(f"  triangles: C_6 has {triangle_count(g1)}, 2K_3 has {triangle_count(g2)}")


def demo_six_vertex_witness() -> None:
    banner("7. The connected non-regular six-vertex witness H1 vs H2")
    g1, g2 = hex1(), hex2()
    print(f"H1 edges: {HEX1_EDGES}")
    print(f"H2 edges: {HEX2_EDGES}")
    print(f"  degrees        : {degrees(g1)}  and  {degrees(g2)}")
    print(f"  connected      : {is_connected(g1)}  and  {is_connected(g2)}")
    print(f"  regular        : {len(set(degrees(g1))) == 1}  and  "
          f"{len(set(degrees(g2))) == 1}")
    print(f"  triangles      : {triangle_count(g1)}  and  {triangle_count(g2)}")
    print(f"  isomorphic     : {is_isomorphic(g1, g2)}")
    print(f"  moment-equal (words of length <= 7): {moment_equivalent(g1, g2, 7)}")
    print()
    print("  Quotient certificate (colour refinement):")
    for name, g in [("H1", g1), ("H2", g2)]:
        colouring = colour_refinement(g)
        sizes, quot, class_deg = quotient_data(g, colouring)
        print(f"    {name}: colouring {colouring}, equitable {is_equitable(g, colouring)}")
        print(f"        class sizes {sizes}, class degrees {class_deg}, B = {quot}")
    print()
    print("  Quotient formula check (moment = size-weighted quotient moment):")
    colouring1 = colour_refinement(g1)
    sizes, quot, class_deg = quotient_data(g1, colouring1)
    for word in ["", "A", "DA", "ADAD", "DDADA"]:
        lhs = word_moment(g1, word)
        rhs = quotient_moment(sizes, quot, class_deg, word)
        print(f"    w = {(word or '(empty)'):<8s} m(H1) = {str(lhs):>10s} "
              f"quotient = {str(rhs):>10s}  match: {lhs == rhs}")
    print()
    print("  Equal decorated walk counts (same invariant, combinatorial form):")
    for n_hops in range(4):
        c1 = all_decorated_walk_counts(g1, n_hops)
        c2 = all_decorated_walk_counts(g2, n_hops)
        print(f"    length {n_hops}: {len(c1)} nonzero patterns, identical: {c1 == c2}")


def demo_equivalence() -> None:
    banner("8. Moments and decorated walk counts have the same strength")
    g = hex1()
    print("Regrouping identity  m(W(a)) = sum_b c(n;b) * prod_i b_i^{a_i}  on H1:")
    for exps in [(1, 0), (2, 1), (1, 1, 1), (0, 2, 1)]:
        word = caterpillar_word(exps)
        lhs = word_moment(g, word)
        counts = all_decorated_walk_counts(g, len(exps) - 1)
        rhs = sum(
            Fraction(count) * Fraction(
                int(eval_pattern(pattern, exps))
            )
            for pattern, count in counts.items()
        )
        print(f"  a = {str(exps):12s} moment = {str(lhs):>10s} "
              f"regrouped = {str(rhs):>10s}  match: {lhs == rhs}")


def eval_pattern(pattern: Sequence[int], exponents: Sequence[int]) -> int:
    """prod_i pattern_i ^ exponents_i."""
    out = 1
    for b, a in zip(pattern, exponents):
        out *= b ** a
    return out


def demo_stars() -> None:
    banner("9. Stars are determined by their moments, and attain M_G = U_G")
    print(f"{'star':<12}{'dim M':>7}{'dim U':>7}{'m(empty)':>10}{'m(A)':>8}{'m(DAD)':>9}")
    for k in range(1, 6):
        g = star(k)
        print(f"{'K_{1,' + str(k) + '}':<12}{cyclic_module_dimension(g):>7}"
              f"{orbit_module_dimension(g):>7}{str(word_moment(g, '')):>10}"
              f"{str(word_moment(g, 'A')):>8}{str(word_moment(g, 'DAD')):>9}")
    print()
    print("  Distinct stars already differ in the empty-word moment (their order),")
    print("  so moment equality inside the star family forces isomorphism.")


def rooted_canonical(adj: Graph, root: int, parent: int) -> str:
    """AHU canonical string of the subtree rooted at `root`."""
    children = sorted(
        rooted_canonical(adj, v, root)
        for v in range(len(adj))
        if adj[root][v] and v != parent
    )
    return "(" + "".join(children) + ")"


def tree_centroids(adj: Graph) -> List[int]:
    """The one or two centroid vertices of a tree."""
    n = len(adj)

    def subtree_sizes(root: int, parent: int) -> int:
        size = 1
        for v in range(n):
            if adj[root][v] and v != parent:
                size += subtree_sizes(v, root)
        sizes[root] = size
        return size

    sizes = [0] * n
    subtree_sizes(0, -1)

    best: List[int] = []
    best_value = n + 1
    for u in range(n):
        pieces = [sizes[v] for v in range(n) if adj[u][v] and sizes[v] < sizes[u]]
        pieces.append(n - 1 - sum(pieces))
        value = max(pieces) if pieces else 0
        if value < best_value:
            best_value, best = value, [u]
        elif value == best_value:
            best.append(u)
    return best


def tree_canonical(adj: Graph) -> str:
    """Canonical form of a free tree: minimal AHU string over its centroids."""
    if len(adj) == 1:
        return "()"
    return min(rooted_canonical(adj, c, -1) for c in tree_centroids(adj))


def generate_trees(n: int) -> List[Graph]:
    """All non-isomorphic trees on n vertices, by leaf extension with canonical dedup."""
    trees: List[Graph] = [graph_from_edges(1, [])]
    for size in range(2, n + 1):
        seen: Dict[str, Graph] = {}
        for t in trees:
            for attach in range(size - 1):
                edges = edge_list(t) + [(attach, size - 1)]
                g = graph_from_edges(size, edges)
                seen.setdefault(tree_canonical(g), g)
        trees = list(seen.values())
    return trees


def demo_trees() -> None:
    banner("10. Moments separate all small trees (evidence for the tree conjecture)")
    print("  For each n, group the non-isomorphic trees by their moment signature")
    print("  (caterpillar words with spine length <= 5 and exponents in {0, 1});")
    print("  a collision would be a counterexample to the tree conjecture.")
    words = [
        caterpillar_word(exps)
        for hops in range(6)
        for exps in product(range(2), repeat=hops + 1)
    ]
    for n in range(2, 12):
        trees = generate_trees(n)
        signatures: Dict[Tuple, List[Graph]] = {}
        for t in trees:
            key = tuple(word_moment(t, w) for w in words)
            signatures.setdefault(key, []).append(t)
        collisions = sum(len(group) - 1 for group in signatures.values())
        print(f"  n = {n}: {len(trees):3d} non-isomorphic trees, "
              f"{len(signatures):3d} distinct moment signatures, "
              f"collisions: {collisions}")


def main() -> None:
    print(__doc__)
    demo_basic_moments()
    demo_isomorphism_invariance()
    demo_caterpillar_expansion()
    demo_degree_recovery()
    demo_modules()
    demo_regular_blindness()
    demo_six_vertex_witness()
    demo_equivalence()
    demo_stars()
    demo_trees()
    banner("Done")


if __name__ == "__main__":
    main()

demos.code:
"""
Adjacency-degree algebras and moment rigidity of graphs
=======================================================

Self-contained numerical demonstration of the results:

  * word moments  m_G(w) = 1^T w(A, D) 1  are isomorphism invariants;
  * the caterpillar expansion
        1^T D^{a_0} A D^{a_1} A ... A D^{a_n} 1
          = sum over walks p_0 ~ ... ~ p_n of  prod_i deg(p_i)^{a_i};
  * moment equality implies equality of the degree distribution and of the
    joint degree distribution N_{a,b};
  * moments equal decorated caterpillar walk counts in strength;
  * the cyclic module M_G = <I, A, D> 1 sits inside the orbit module U_G,
    and dim M_G = 1 exactly for regular graphs;
  * regular blindness:  m_G(w) = k^{|w|} n  for every k-regular graph;
  * the quotient formula on an equitable colouring, and the connected
    non-regular six-vertex pair H1, H2 that it certifies as
    moment-equivalent but non-isomorphic.

Pure Python + standard library only (fractions used for exact arithmetic).
Run:  python demo.py
"""

from __future__ import annotations

from fractions import Fraction
from itertools import combinations, permutations, product
from typing import Dict, Iterable, List, Sequence, Tuple

Graph = List[List[int]]  # adjacency matrix as a list of rows of 0/1
Word = str  # a string over the alphabet {"A", "D"}


# ----------------------------------------------------------------------
# Graph construction helpers
# ----------------------------------------------------------------------


def graph_from_edges(n: int, edges: Iterable[Tuple[int, int]]) -> Graph:
    """Build the n-vertex adjacency matrix of a simple graph from an edge list."""
    adj: Graph = [[0] * n for _ in range(n)]
    for u, v in edges:
        if u == v:
            raise ValueError("simple graphs have no loops")
        adj[u][v] = 1
        adj[v][u] = 1
    return adj


def degrees(adj: Graph) -> List[int]:
    """Degree sequence, indexed by vertex."""
    return [sum(row) for row in adj]


def edge_list(adj: Graph) -> List[Tuple[int, int]]:
    """Undirected edges as sorted pairs."""
    n = len(adj)
    return [(u, v) for u in range(n) for v in range(u + 1, n) if adj[u][v]]


def is_connected(adj: Graph) -> bool:
    """Breadth-first reachability from vertex 0."""
    n = len(adj)
    if n == 0:
        return True
    seen = {0}
    stack = [0]
    while stack:
        u = stack.pop()
        for v in range(n):
            if adj[u][v] and v not in seen:
                seen.add(v)
                stack.append(v)
    return len(seen) == n


def triangle_count(adj: Graph) -> int:
    """Number of unordered triangles."""
    n = len(adj)
    return sum(
        1
        for a, b, c in combinations(range(n), 3)
        if adj[a][b] and adj[b][c] and adj[a][c]
    )


def is_isomorphic(g1: Graph, g2: Graph) -> bool:
    """Brute-force isomorphism test (only used on tiny graphs)."""
    n = len(g1)
    if n != len(g2) or sorted(degrees(g1)) != sorted(degrees(g2)):
        return False
    for perm in permutations(range(n)):
        if all(g1[u][v] == g2[perm[u]][perm[v]] for u in range(n) for v in range(n)):
            return True
    return False


# ----------------------------------------------------------------------
# Word moments
# ----------------------------------------------------------------------


def apply_letter(adj: Graph, deg: Sequence[int], letter: str,
                 x: Sequence[Fraction]) -> List[Fraction]:
    """Apply A (hopping) or D (degree potential) to a vector, in O(n^2)/O(n)."""
    n = len(adj)
    if letter == "A":
        return [sum(x[v] for v in range(n) if adj[u][v]) for u in range(n)]
    if letter == "D":
        return [Fraction(deg[u]) * x[u] for u in range(n)]
    raise ValueError(f"unknown letter {letter!r}")


def word_moment(adj: Graph, word: Word) -> Fraction:
    """m_G(w) = 1^T w(A, D) 1, computed by right-to-left vector propagation."""
    n = len(adj)
    deg = degrees(adj)
    x: List[Fraction] = [Fraction(1)] * n
    for letter in reversed(word):
        x = apply_letter(adj, deg, letter, x)
    return sum(x, Fraction(0))


def all_words(max_len: int) -> List[Word]:
    """All words over {A, D} of length at most max_len, shortest first."""
    words: List[Word] = [""]
    for length in range(1, max_len + 1):
        words.extend("".join(t) for t in product("AD", repeat=length))
    return words


def moment_vector(adj: Graph, max_len: int) -> Dict[Word, Fraction]:
    """The full moment table up to a given word length."""
    return {w: word_moment(adj, w) for w in all_words(max_len)}


def moment_equivalent(g1: Graph, g2: Graph, max_len: int = 6) -> bool:
    """Test moment equality for all words up to a given length."""
    return moment_vector(g1, max_len) == moment_vector(g2, max_len)


# ----------------------------------------------------------------------
# Caterpillar expansion: moments as decorated walk sums
# ----------------------------------------------------------------------


def caterpillar_word(exponents: Sequence[int]) -> Word:
    """D^{a_0} A D^{a_1} A ... A D^{a_n} as a word over {A, D}."""
    return "A".join("D" * a for a in exponents)


def decorated_walk_sum(adj: Graph, exponents: Sequence[int]) -> Fraction:
    """Sum over all walks p_0 ~ ... ~ p_n of prod_i deg(p_i)^{a_i}, by brute force."""
    n_hops = len(exponents) - 1
    n = len(adj)
    deg = degrees(adj)
    total = Fraction(0)
    for walk in product(range(n), repeat=n_hops + 1):
        if all(adj[walk[i]][walk[i + 1]] for i in range(n_hops)):
            weight = Fraction(1)
            for i, a in enumerate(exponents):
                weight *= Fraction(deg[walk[i]]) ** a
            total += weight
    return total


def decorated_walk_count(adj: Graph, pattern: Sequence[int]) -> int:
    """c_G(n; b): number of walks whose degree sequence is exactly `pattern`."""
    n_hops = len(pattern) - 1
    n = len(adj)
    deg = degrees(adj)
    count = 0
    for walk in product(range(n), repeat=n_hops + 1):
        if all(adj[walk[i]][walk[i + 1]] for i in range(n_hops)) and all(
            deg[walk[i]] == pattern[i] for i in range(n_hops + 1)
        ):
            count += 1
    return count


def all_decorated_walk_counts(adj: Graph, n_hops: int) -> Dict[Tuple[int, ...], int]:
    """All nonzero decorated walk counts of a given length."""
    n = len(adj)
    deg = degrees(adj)
    counts: Dict[Tuple[int, ...], int] = {}
    for walk in product(range(n), repeat=n_hops + 1):
        if all(adj[walk[i]][walk[i + 1]] for i in range(n_hops)):
            key = tuple(deg[v] for v in walk)
            counts[key] = counts.get(key, 0) + 1
    return counts


# ----------------------------------------------------------------------
# Degree and joint-degree statistics
# ----------------------------------------------------------------------


def degree_distribution(adj: Graph) -> Dict[int, int]:
    """Number of vertices of each degree."""
    dist: Dict[int, int] = {}
    for d in degrees(adj):
        dist[d] = dist.get(d, 0) + 1
    return dist


def joint_degree_counts(adj: Graph) -> Dict[Tuple[int, int], int]:
    """N_{a,b}: ordered adjacent pairs (u, v) with deg u = a, deg v = b."""
    n = len(adj)
    deg = degrees(adj)
    counts: Dict[Tuple[int, int], int] = {}
    for u in range(n):
        for v in range(n):
            if adj[u][v]:
                key = (deg[u], deg[v])
                counts[key] = counts.get(key, 0) + 1
    return counts


def lagrange_basis(nodes: Sequence[int], target: int) -> List[Fraction]:
    """Coefficients of the Lagrange basis polynomial that is 1 at `target`, 0 elsewhere."""
    coeffs = [Fraction(1)]
    for node in nodes:
        if node == target:
            continue
        # multiply by (x - node) / (target - node)
        scale = Fraction(1, target - node)
        new = [Fraction(0)] * (len(coeffs) + 1)
        for i, c in enumerate(coeffs):
            new[i + 1] += c * scale
            new[i] -= c * node * scale
        coeffs = new
    return coeffs


def degree_distribution_from_moments(moments: Dict[Word, Fraction], n: int) -> Dict[int, int]:
    """Recover the degree distribution from the pure-degree moments 1^T D^k 1."""
    power_sums = [moments["D" * k] for k in range(n)]
    nodes = list(range(n))
    dist: Dict[int, int] = {}
    for d in nodes:
        coeffs = lagrange_basis(nodes, d)
        value = sum(c * power_sums[i] for i, c in enumerate(coeffs))
        if value != 0:
            dist[d] = int(value)
    return dist


def joint_degree_from_moments(adj: Graph, n: int) -> Dict[Tuple[int, int], int]:
    """Recover N_{a,b} from the moments 1^T D^i A D^j 1 by double interpolation."""
    raw = {
        (i, j): word_moment(adj, "D" * i + "A" + "D" * j)
        for i in range(n)
        for j in range(n)
    }
    nodes = list(range(n))
    out: Dict[Tuple[int, int], int] = {}
    for a in nodes:
        ca = lagrange_basis(nodes, a)
        for b in nodes:
            cb = lagrange_basis(nodes, b)
            value = sum(
                ca[i] * cb[j] * raw[(i, j)]
                for i in range(len(ca))
                for j in range(len(cb))
            )
            if value != 0:
                out[(a, b)] = int(value)
    return out


# ----------------------------------------------------------------------
# The cyclic module M_G and the orbit module U_G
# ----------------------------------------------------------------------


def rref_rank(rows: List[List[Fraction]]) -> int:
    """Rank of a matrix over the rationals by Gaussian elimination."""
    mat = [row[:] for row in rows]
    rank = 0
    ncols = len(mat[0]) if mat else 0
    for col in range(ncols):
        pivot = next((r for r in range(rank, len(mat)) if mat[r][col] != 0), None)
        if pivot is None:
            continue
        mat[rank], mat[pivot] = mat[pivot], mat[rank]
        inv = Fraction(1) / mat[rank][col]
        mat[rank] = [x * inv for x in mat[rank]]
        for r in range(len(mat)):
            if r != rank and mat[r][col] != 0:
                factor = mat[r][col]
                mat[r] = [x - factor * y for x, y in zip(mat[r], mat[rank])]
        rank += 1
    return rank


def cyclic_module_basis(adj: Graph, max_len: int = 8) -> List[List[Fraction]]:
    """Vectors w(A, D) 1 for all words w up to a given length (a spanning set of M_G)."""
    n = len(adj)
    deg = degrees(adj)
    vectors: List[List[Fraction]] = []
    for word in all_words(max_len):
        x: List[Fraction] = [Fraction(1)] * n
        for letter in reversed(word):
            x = apply_letter(adj, deg, letter, x)
        vectors.append(x)
    return vectors


def cyclic_module_dimension(adj: Graph, max_len: int = 8) -> int:
    """dim M_G, computed from a spanning set (stabilises well before max_len)."""
    return rref_rank(cyclic_module_basis(adj, max_len))


def automorphisms(adj: Graph) -> List[Tuple[int, ...]]:
    """All automorphisms, by brute force (tiny graphs only)."""
    n = len(adj)
    return [
        perm
        for perm in permutations(range(n))
        if all(adj[u][v] == adj[perm[u]][perm[v]] for u in range(n) for v in range(n))
    ]


def orbit_partition(adj: Graph) -> List[List[int]]:
    """Orbits of the automorphism group on vertices."""
    n = len(adj)
    auts = automorphisms(adj)
    seen = [False] * n
    orbits: List[List[int]] = []
    for v in range(n):
        if seen[v]:
            continue
        orbit = sorted({perm[v] for perm in auts})
        for u in orbit:
            seen[u] = True
        orbits.append(orbit)
    return orbits


def orbit_module_dimension(adj: Graph) -> int:
    """dim U_G = number of automorphism orbits."""
    return len(orbit_partition(adj))


# ----------------------------------------------------------------------
# Colour refinement and the quotient formula
# ----------------------------------------------------------------------


def colour_refinement(adj: Graph) -> List[int]:
    """Stable colouring (1-WL): returns a canonical integer colour per vertex."""
    n = len(adj)
    colours = [0] * n
    while True:
        signature = [
            (colours[u], tuple(sorted(colours[v] for v in range(n) if adj[u][v])))
            for u in range(n)
        ]
        order = {sig: i for i, sig in enumerate(sorted(set(signature)))}
        new = [order[sig] for sig in signature]
        if new == colours:
            return colours
        colours = new


def is_equitable(adj: Graph, colouring: Sequence[int]) -> bool:
    """Check the equitable-partition condition directly."""
    n = len(adj)
    palette = sorted(set(colouring))
    for u in range(n):
        for v in range(n):
            if colouring[u] != colouring[v]:
                continue
            for kappa in palette:
                cu = sum(1 for w in range(n) if adj[u][w] and colouring[w] == kappa)
                cv = sum(1 for w in range(n) if adj[v][w] and colouring[w] == kappa)
                if cu != cv:
                    return False
    return True


def quotient_data(adj: Graph, colouring: Sequence[int]):
    """Class sizes, quotient matrix B, and class degrees Delta of an equitable colouring."""
    n = len(adj)
    palette = sorted(set(colouring))
    sizes = [sum(1 for v in range(n) if colouring[v] == kappa) for kappa in palette]
    reps = [next(v for v in range(n) if colouring[v] == kappa) for kappa in palette]
    deg = degrees(adj)
    quot = [
        [sum(1 for w in range(n) if adj[r][w] and colouring[w] == lam) for lam in palette]
        for r in reps
    ]
    class_deg = [deg[r] for r in reps]
    return sizes, quot, class_deg


def quotient_moment(sizes: Sequence[int], quot: Sequence[Sequence[int]],
                    class_deg: Sequence[int], word: Word) -> Fraction:
    """sum_kappa |kappa| * (w(B, Delta) 1)_kappa -- the quotient formula's right-hand side."""
    c = len(sizes)
    x: List[Fraction] = [Fraction(1)] * c
    for letter in reversed(word):
        if letter == "A":
            x = [sum(Fraction(quot[k][l]) * x[l] for l in range(c)) for k in range(c)]
        else:
            x = [Fraction(class_deg[k]) * x[k] for k in range(c)]
    return sum(Fraction(sizes[k]) * x[k] for k in range(c))


# ----------------------------------------------------------------------
# Named graphs
# ----------------------------------------------------------------------


def star(n_leaves: int) -> Graph:
    """K_{1,n}: centre 0 joined to n leaves."""
    return graph_from_edges(n_leaves + 1, [(0, i) for i in range(1, n_leaves + 1)])


def path(n: int) -> Graph:
    """The path on n vertices."""
    return graph_from_edges(n, [(i, i + 1) for i in range(n - 1)])


def cycle(n: int) -> Graph:
    """The cycle C_n."""
    return graph_from_edges(n, [(i, (i + 1) % n) for i in range(n)])


def two_triangles() -> Graph:
    """2K_3: two disjoint triangles on six vertices."""
    return graph_from_edges(6, [(0, 1), (1, 2), (0, 2), (3, 4), (4, 5), (3, 5)])


HEX1_EDGES = [(0, 3), (0, 4), (0, 5), (1, 3), (1, 5), (2, 3), (2, 4)]
HEX2_EDGES = [(0, 1), (0, 2), (0, 5), (1, 5), (2, 3), (2, 4), (3, 4)]


def hex1() -> Graph:
    """H1: the triangle-free (bipartite) six-vertex witness."""
    return graph_from_edges(6, HEX1_EDGES)


def hex2() -> Graph:
    """H2: the six-vertex witness containing a triangle."""
    return graph_from_edges(6, HEX2_EDGES)


def relabel(adj: Graph, perm: Sequence[int]) -> Graph:
    """Relabel vertices: new vertex perm[u] plays the role of old vertex u."""
    n = len(adj)
    out: Graph = [[0] * n for _ in range(n)]
    for u in range(n):
        for v in range(n):
            out[perm[u]][perm[v]] = adj[u][v]
    return out


# ----------------------------------------------------------------------
# Demonstrations
# ----------------------------------------------------------------------


def banner(title: str) -> None:
    print()
    print("=" * 72)
    print(title)
    print("=" * 72)


def demo_basic_moments() -> None:
    banner("1. Basic moments: order, size, degree power sums, decorated edges")
    g = path(5)
    n = len(g)
    print(f"Graph: path on {n} vertices, degrees {degrees(g)}")
    print(f"  m(empty)  = {word_moment(g, '')}        (= number of vertices {n})")
    print(f"  m(A)      = {word_moment(g, 'A')}        (= 2|E| = {2 * len(edge_list(g))})")
    for k in range(1, 4):
        lhs = word_moment(g, "D" * k)
        rhs = sum(d ** k for d in degrees(g))
        print(f"  m(D^{k})    = {lhs}       (= sum of d^{k} = {rhs})  match: {lhs == rhs}")
    deg = degrees(g)
    rhs = sum(2 * deg[u] * deg[v] for u, v in edge_list(g))
    print(f"  m(DAD)    = {word_moment(g, 'DAD')}      (= 2 * sum_{{uv in E}} d_u d_v = {rhs})")


