def demo_equivalence() -> None:
    banner("8. Moments and decorated walk counts have the same strength")
    g = hex1()
    print("Regrouping identity  m(W(a)) = sum_b c(n;b) * prod_i b_i^{a_i}  on H1:")
    for exps in [(1, 0), (2, 1), (1, 1, 1), (0, 2, 1)]:
        word = caterpillar_word(exps)
        lhs = word_moment(g, word)
        counts = all_decorated_walk_counts(g, len(exps) - 1)
        rhs = sum(
            Fraction(count) * Fraction(
                int(eval_pattern(pattern, exps))
            )
            for pattern, count in counts.items()
        )
        print(f"  a = {str(exps):12s} moment = {str(lhs):>10s} "
              f"regrouped = {str(rhs):>10s}  match: {lhs == rhs}")


def eval_pattern(pattern: Sequence[int], exponents: Sequence[int]) -> int:
    """prod_i pattern_i ^ exponents_i."""
    out = 1
    for b, a in zip(pattern, exponents):
        out *= b ** a
    return out


def demo_stars() -> None:
    banner("9. Stars are determined by their moments, and attain M_G = U_G")
    print(f"{'star':<12}{'dim M':>7}{'dim U':>7}{'m(empty)':>10}{'m(A)':>8}{'m(DAD)':>9}")
    for k in range(1, 6):
        g = star(k)
        print(f"{'K_{1,' + str(k) + '}':<12}{cyclic_module_dimension(g):>7}"
              f"{orbit_module_dimension(g):>7}{str(word_moment(g, '')):>10}"
              f"{str(word_moment(g, 'A')):>8}{str(word_moment(g, 'DAD')):>9}")
    print()
    print("  Distinct stars already differ in the empty-word moment (their order),")
    print("  so moment equality inside the star family forces isomorphism.")


def rooted_canonical(adj: Graph, root: int, parent: int) -> str:
    """AHU canonical string of the subtree rooted at `root`."""
    children = sorted(
        rooted_canonical(adj, v, root)
        for v in range(len(adj))
        if adj[root][v] and v != parent
    )
    return "(" + "".join(children) + ")"


def tree_centroids(adj: Graph) -> List[int]:
    """The one or two centroid vertices of a tree."""
    n = len(adj)

    def subtree_sizes(root: int, parent: int) -> int:
        size = 1
        for v in range(n):
            if adj[root][v] and v != parent:
                size += subtree_sizes(v, root)
        sizes[root] = size
        return size

    sizes = [0] * n
    subtree_sizes(0, -1)

    best: List[int] = []
    best_value = n + 1
    for u in range(n):
        pieces = [sizes[v] for v in range(n) if adj[u][v] and sizes[v] < sizes[u]]
        pieces.append(n - 1 - sum(pieces))
        value = max(pieces) if pieces else 0
        if value < best_value:
            best_value, best = value, [u]
        elif value == best_value:
            best.append(u)
    return best


def tree_canonical(adj: Graph) -> str:
    """Canonical form of a free tree: minimal AHU string over its centroids."""
    if len(adj) == 1:
        return "()"
    return min(rooted_canonical(adj, c, -1) for c in tree_centroids(adj))


def generate_trees(n: int) -> List[Graph]:
    """All non-isomorphic trees on n vertices, by leaf extension with canonical dedup."""
    trees: List[Graph] = [graph_from_edges(1, [])]
    for size in range(2, n + 1):
        seen: Dict[str, Graph] = {}
        for t in trees:
            for attach in range(size - 1):
                edges = edge_list(t) + [(attach, size - 1)]
                g = graph_from_edges(size, edges)
                seen.setdefault(tree_canonical(g), g)
        trees = list(seen.values())
    return trees


def demo_trees() -> None:
    banner("10. Moments separate all small trees (evidence for the tree conjecture)")
    print("  For each n, group the non-isomorphic trees by their moment signature")
    print("  (caterpillar words with spine length <= 5 and exponents in {0, 1});")
    print("  a collision would be a counterexample to the tree conjecture.")
    words = [
        caterpillar_word(exps)
        for hops in range(6)
        for exps in product(range(2), repeat=hops + 1)
    ]
    for n in range(2, 12):
        trees = generate_trees(n)
        signatures: Dict[Tuple, List[Graph]] = {}
        for t in trees:
            key = tuple(word_moment(t, w) for w in words)
            signatures.setdefault(key, []).append(t)
        collisions = sum(len(group) - 1 for group in signatures.values())
        print(f"  n = {n}: {len(trees):3d} non-isomorphic trees, "
              f"{len(signatures):3d} distinct moment signatures, "
              f"collisions: {collisions}")


def main() -> None:
    print(__doc__)
    demo_basic_moments()
    demo_isomorphism_invariance()
    demo_caterpillar_expansion()
    demo_degree_recovery()
    demo_modules()
    demo_regular_blindness()
    demo_six_vertex_witness()
    demo_equivalence()
    demo_stars()
    demo_trees()
    banner("Done")


if __name__ == "__main__":
    main()

"""Tree-separation census: do adjacency-degree moments distinguish all small trees?

The principal form of McKay's theorem predicts that no two non-isomorphic trees
share all their adjacency-degree word moments. This script tests the prediction
exhaustively for every tree on at most twelve vertices.

For each n it
  1. generates all non-isomorphic trees on n vertices by leaf extension,
     de-duplicating with the AHU canonical form of a free tree;
  2. computes the moment signature of each tree -- the tuple of moments
     1^T w(A, D) 1 for all words w over {A, D} of bounded length;
  3. groups the trees by signature and reports any collision.

A collision would be a counterexample to the conjecture. It also compares the
moment signature with two weaker fingerprints -- the degree sequence and the plain
walk-count sequence 1^T A^k 1 -- to quantify how much the degree decoration adds.

Pure standard library. Run:  python demo2.py
"""

from __future__ import annotations

from itertools import product
from typing import Dict, List, Sequence, Tuple

Graph = List[List[int]]


def graph_from_edges(n: int, edges: Sequence[Tuple[int, int]]) -> Graph:
    """Adjacency matrix from an edge list."""
    adj: Graph = [[0] * n for _ in range(n)]
    for u, v in edges:
        adj[u][v] = adj[v][u] = 1
    return adj


def edge_list(adj: Graph) -> List[Tuple[int, int]]:
    """Undirected edges as sorted pairs."""
    n = len(adj)
    return [(u, v) for u in range(n) for v in range(u + 1, n) if adj[u][v]]


def degrees(adj: Graph) -> List[int]:
    """Degree sequence, indexed by vertex."""
    return [sum(row) for row in adj]


def word_moment(adj: Graph, word: str) -> int:
    """1^T w(A, D) 1 by right-to-left vector propagation."""
    n = len(adj)
    deg = degrees(adj)
    x = [1] * n
    for letter in reversed(word):
        if letter == "A":
            x = [sum(x[v] for v in range(n) if adj[u][v]) for u in range(n)]
        else:
            x = [deg[u] * x[u] for u in range(n)]
    return sum(x)


def caterpillar_words(max_hops: int, max_exponent: int) -> List[str]:
    """Caterpillar words D^{a_0} A ... A D^{a_n} with n <= max_hops, a_i <= max_exponent.

    Every word in A and D is a caterpillar word, so this is a truncation of the
    full moment data by spine length and decoration weight.
    """
    words: List[str] = []
    for hops in range(max_hops + 1):
        for exponents in product(range(max_exponent + 1), repeat=hops + 1):
            words.append("A".join("D" * a for a in exponents))
    return words


def moment_signature(adj: Graph, max_hops: int = 5,
                     max_exponent: int = 1) -> Tuple[int, ...]:
    """The tuple of caterpillar moments up to the given spine length and decoration."""
    return tuple(word_moment(adj, w) for w in caterpillar_words(max_hops, max_exponent))


def walk_signature(adj: Graph, max_len: int) -> Tuple[int, ...]:
    """The undecorated walk counts 1^T A^k 1 for k <= max_len."""
    return tuple(word_moment(adj, "A" * k) for k in range(max_len + 1))


def degree_signature(adj: Graph) -> Tuple[int, ...]:
    """The sorted degree sequence."""
    return tuple(sorted(degrees(adj)))


def rooted_canonical(adj: Graph, root: int, parent: int) -> str:
    """AHU canonical string of the subtree rooted at `root`."""
    kids = sorted(
        rooted_canonical(adj, v, root)
        for v in range(len(adj))
        if adj[root][v] and v != parent
    )
    return "(" + "".join(kids) + ")"


def tree_centroids(adj: Graph) -> List[int]:
    """The one or two centroids of a tree."""
    n = len(adj)
    sizes = [0] * n

    def walk(root: int, parent: int) -> int:
        size = 1
        for v in range(n):
            if adj[root][v] and v != parent:
                size += walk(v, root)
        sizes[root] = size
        return size

    walk(0, -1)
    best: List[int] = []
    best_value = n + 1
    for u in range(n):
        pieces = [sizes[v] for v in range(n) if adj[u][v] and sizes[v] < sizes[u]]
        pieces.append(n - 1 - sum(pieces))
        value = max(pieces) if pieces else 0
        if value < best_value:
            best_value, best = value, [u]
        elif value == best_value:
            best.append(u)
    return best


def tree_canonical(adj: Graph) -> str:
    """Canonical form of a free tree: the minimal AHU string over its centroids."""
    if len(adj) == 1:
        return "()"
    return min(rooted_canonical(adj, c, -1) for c in tree_centroids(adj))


def generate_trees(n: int) -> List[Graph]:
    """All non-isomorphic trees on n vertices, by leaf extension with canonical dedup."""
    trees: List[Graph] = [graph_from_edges(1, [])]
    for size in range(2, n + 1):
        seen: Dict[str, Graph] = {}
        for t in trees:
            for attach in range(size - 1):
                g = graph_from_edges(size, edge_list(t) + [(attach, size - 1)])
                seen.setdefault(tree_canonical(g), g)
        trees = list(seen.values())
    return trees


def census(max_vertices: int = 12, max_hops: int = 5) -> None:
    """Print the separation census for all trees up to `max_vertices` vertices."""
    header = (f"{'n':>3} {'trees':>7} {'by degrees':>11} {'by walks':>10} "
              f"{'by moments':>11} {'collisions':>11}")
    print(header)
    print("-" * len(header))
    for n in range(2, max_vertices + 1):
        trees = generate_trees(n)
        by_degree = len({degree_signature(t) for t in trees})
        by_walk = len({walk_signature(t, 2 * n) for t in trees})
        signatures: Dict[Tuple[int, ...], int] = {}
        for t in trees:
            key = moment_signature(t, max_hops)
            signatures[key] = signatures.get(key, 0) + 1
        collisions = sum(c - 1 for c in signatures.values())
        print(f"{n:>3} {len(trees):>7} {by_degree:>11} {by_walk:>10} "
              f"{len(signatures):>11} {collisions:>11}")


def show_smallest_walk_collision() -> None:
    """Exhibit the smallest pair of trees that walk counts confuse but moments separate."""
    for n in range(2, 14):
        trees = generate_trees(n)
        buckets: Dict[Tuple[int, ...], List[Graph]] = {}
        for t in trees:
            buckets.setdefault(walk_signature(t, 2 * n), []).append(t)
        clashes = [group for group in buckets.values() if len(group) > 1]
        if clashes:
            group = clashes[0]
            print(f"\nSmallest walk-count collision among trees: n = {n}")
            for t in group:
                print(f"  edges {edge_list(t)}  degrees {sorted(degrees(t))}")
            sigs = {moment_signature(t) for t in group}
            print(f"  distinct moment signatures within the group: {len(sigs)} "
                  f"(so the degree decoration separates them: {len(sigs) == len(group)})")
            return
    print("\nNo walk-count collision found in the tested range.")


if __name__ == "__main__":
    print(__doc__)
    census()
    show_smallest_walk_collision()

